<template>
  <transition name="museum-orientation"><div v-if="visible" class="museum-orientation" role="status"><svg viewBox="0 0 28 28" aria-hidden="true"><rect x="8" y="4" width="12" height="20" rx="2" transform="rotate(30 14 14)"/><path d="M3 10a11 11 0 0 1 5-6M3 5v5h5m17 8a11 11 0 0 1-5 6m5-1v-5h-5"/></svg><span>More room in landscape</span><button type="button" aria-label="Keep portrait" @click="dismiss">×</button></div></transition>
</template>
<script>
import { museumSession, updateMuseumSession } from '../../utils/viewMuseumSession';
export default {
  data: () => ({ visible: false }),
  mounted() { this._portrait = matchMedia('(max-width: 767px) and (orientation: portrait)'); this.sync(); this._portrait.addEventListener('change', this.sync); },
  beforeUnmount() { this._portrait?.removeEventListener('change', this.sync); },
  methods: {
    sync() { if (this.visible && !this._portrait.matches) this.dismiss(); else this.visible = this._portrait.matches && !museumSession().orientationSeen; },
    dismiss() { this.visible = false; updateMuseumSession({ orientationSeen: true }); },
  },
};
</script>
