.museum-orientation { position:absolute; top:calc(68px + env(safe-area-inset-top)); left:50%; transform:translateX(-50%); z-index:9; display:flex; align-items:center; gap:10px; width:max-content; max-width:calc(100% - 32px); box-sizing:border-box; padding:9px 10px 9px 15px; border:1px solid var(--ex-border,#d5d4c9); border-radius:30px; background:var(--ex-paper,#f5f3ec); color:var(--ex-ink,#34372f); box-shadow:0 5px 25px #1111; font:12px 'Quattrocento Sans',sans-serif; }
.museum-orientation svg { width:24px; height:24px; fill:none; stroke:currentColor; stroke-width:1; }
.museum-orientation button { border:0; background:none; color:inherit; font:20px/1 sans-serif; width:36px; height:32px; cursor:pointer; }
